-- JAKRoute / Supabase
-- Jalankan file ini PERTAMA lewat Supabase SQL Editor.
-- Sumber: Lantai 2 Palmerah Fella.geojson
-- Hasil: 55 polygon Lantai 2. Semua polygon diperlakukan sebagai obstacle.
-- Skrip aman dijalankan ulang: data sumber akan di-upsert berdasarkan id.
-- Tabel lama sengaja TIDAK dihapus agar migrasi dapat dilakukan bertahap.

begin;

create schema if not exists extensions;
create extension if not exists postgis with schema extensions;

create table if not exists public.station_blocks (
  id text primary key,
  station_id text not null,
  floor smallint not null,
  source_no smallint not null,
  name text not null,
  block_type text not null default 'facility_block',
  is_obstacle boolean not null default true,
  geom extensions.geometry(Polygon, 4326) not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint station_blocks_source_unique unique (station_id, floor, source_no),
  constraint station_blocks_floor_check check (floor >= 0)
);

create index if not exists station_blocks_geom_gix
  on public.station_blocks using gist (geom);

create index if not exists station_blocks_station_floor_idx
  on public.station_blocks (station_id, floor);

alter table public.station_blocks enable row level security;

grant usage on schema public to anon, authenticated;
grant select on public.station_blocks to anon, authenticated;

drop policy if exists station_blocks_public_read on public.station_blocks;
create policy station_blocks_public_read
  on public.station_blocks
  for select
  to anon, authenticated
  using (true);

insert into public.station_blocks (
  id, station_id, floor, source_no, name, block_type,
  is_obstacle, geom, metadata
)
