on conflict (id) do update set
  station_id = excluded.station_id,
  floor = excluded.floor,
  source_no = excluded.source_no,
  name = excluded.name,
  block_type = excluded.block_type,
  is_obstacle = excluded.is_obstacle,
  geom = excluded.geom,
  metadata = excluded.metadata,
  updated_at = now();

do $$
declare
  imported_count integer;
begin
  select count(*) into imported_count
  from public.station_blocks
  where station_id = 'palmerah'
    and floor = 2
    and id like 'palmerah_lt2_block_%';

  if imported_count <> 55 then
    raise exception 'Import station_blocks tidak lengkap: ditemukan %, seharusnya 55.', imported_count;
  end if;

  if exists (
    select 1
    from public.station_blocks
    where station_id = 'palmerah'
      and floor = 2
      and id like 'palmerah_lt2_block_%'
      and (
        extensions.ST_SRID(geom) <> 4326
        or not extensions.ST_IsValid(geom)
        or is_obstacle is not true
      )
  ) then
    raise exception 'Ada geometry/obstacle station_blocks yang tidak valid.';
  end if;
end
$$;

commit;

-- Cek cepat setelah selesai:
select
  count(*) as jumlah_block,
  bool_and(is_obstacle) as semua_obstacle,
  bool_and(extensions.ST_IsValid(geom)) as semua_geometry_valid
from public.station_blocks
where station_id = 'palmerah' and floor = 2;
